下面的函数无法把分配到的内存交给调用方，且存在泄漏。指出问题并改正：

```c
void alloc(int *p, size_t n) {
    p = malloc(n * sizeof(int));
}
int main(void) {
    int *buf = NULL;
    alloc(buf, 10);
    /* buf 仍是 NULL */
}
```

answer.reference_code:
void alloc(int **out, size_t n) {
    *out = malloc(n * sizeof(int));
}
int main(void) {
    int *buf = NULL;
    alloc(&buf, 10);
    if (!buf) { return 1; }
    free(buf);
    buf = NULL;
    return 0;
}

void reverseString(char *s, int sSize) {
    int i = 0, j = sSize - 1;
    while (i < j) {
        char t = s[i];
        s[i++] = s[j];
        s[j--] = t;
    }
}

void moveZeroes(int *nums, int numsSize) {
    int slow = 0;
    for (int fast = 0; fast < numsSize; fast++) {
        if (nums[fast] != 0) {
            int t = nums[slow];
            nums[slow++] = nums[fast];
            nums[fast] = t;
        }
    }
}
